-- generated by tools/gencatalog, do not edit by hand

CREATE TABLE positions (
    id BIGINT PRIMARY KEY GENERATED ALWAYS AS IDENTITY,
    code VARCHAR(64) NOT NULL,
    name VARCHAR(128) NOT NULL,
    is_deleted BOOLEAN NOT NULL DEFAULT FALSE
);

CREATE TABLE position_revisions (
    id              BIGINT       PRIMARY KEY GENERATED ALWAYS AS IDENTITY,
    position_id BIGINT       NOT NULL REFERENCES positions(id) ON DELETE CASCADE,
    revision_number INTEGER      NOT NULL CHECK (revision_number >= 1),
    change          JSONB        NOT NULL,
    changed_by      UUID         NOT NULL,
    changed_at      TIMESTAMPTZ  NOT NULL DEFAULT now(),

    CONSTRAINT uq_position_revisions_revision
        UNIQUE (position_id, revision_number)
);

CREATE UNIQUE INDEX uq_positions_code
    ON positions (code);

CREATE INDEX idx_positions_active
    ON positions (id)
    WHERE is_deleted = FALSE;

CREATE INDEX idx_position_revisions_position_id
    ON position_revisions (position_id);

CREATE INDEX idx_position_revisions_covering_agg
    ON position_revisions (position_id, revision_number DESC)
    INCLUDE (changed_at, changed_by, change);

CREATE INDEX idx_position_revisions_changed_at
    ON position_revisions (changed_at);

CREATE OR REPLACE VIEW v_expanded_position AS
SELECT
    t.id,
    t.code,
    t.name,
    t.is_deleted,
    agg.revision,
    agg.last_changer,
    agg.created_at,
    agg.updated_at,
    agg.deleted_at
FROM positions t
LEFT JOIN (
    SELECT
        position_id,
        MAX(revision_number) AS revision,
        MAX(changed_at) AS updated_at,
        (ARRAY_AGG(changed_by ORDER BY revision_number DESC))[1] AS last_changer,
        MIN(changed_at) FILTER (WHERE revision_number = 1) AS created_at,
        MAX(changed_at) FILTER (
            WHERE change @> '[{"path": "/is_deleted", "value": true}]'::jsonb
        ) AS deleted_at
    FROM position_revisions
    GROUP BY position_id
) agg ON agg.position_id = t.id;

COMMENT ON TABLE positions IS
    'Positions employees are assigned to. Stores the current state of each record.';

COMMENT ON TABLE position_revisions IS
    'Immutable audit log of changes applied to positions. Read-only from the application perspective.';

COMMENT ON VIEW v_expanded_position IS
    'Read-only view that enriches each position with its latest revision number, '
    'last changer UUID, and lifecycle timestamps derived from the revision log.';
